  const interviewLink=path.relative(path.resolve(out),path.resolve(manifest.interview.path)).split(path.sep).join('/');
  const header=['# Premium audit first-pass report','','PROVISIONAL â€” employer/auditor confirmation required before sign-off. These are classification and payroll proposals, not quotes.','',`Rule authority: [July 2025 guide](${manifest.guide.url}) and [original interview](${interviewLink}) (10:56â€“11:01). CG identifiers describe class codes; interview clarifications have timestamps, not fabricated CG identifiers.`,'','## Call priority','',...priority.slice(0,2).map((r,i)=>`${i+1}. **${r.title}**: $${usd(r.exposure)} of payroll affected by class movement/additions using the comparison below; ${r.issues.length} open items. ${r.review.callReason}`),'','Priority compares payroll subject to movement plus payroll additions, not premium or an invented risk rate. This is my triage judgment; class severity and evidence uncertainty also matter. For a single-employer run, ranking is limited to that employer.',''];
